-- Baseline schema for the e-commerce database.
--
-- Generated by letting Hibernate create the schema from the JPA entities
-- (ddl-auto=create) against PostgreSQL 16 and dumping the result, so it matches
-- what spring.jpa.hibernate.ddl-auto=validate expects on startup byte for byte.
--
-- Databases that predate Flyway (created by the old ddl-auto=update) are stamped
-- at this version by spring.flyway.baseline-on-migrate=true rather than having
-- this script replayed against them. Fresh databases get it applied normally.
--
-- Do not edit this file. Schema changes go in a new V2__*.sql.

-- Name: cart; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.cart (
    created_date timestamp(6) with time zone,
    id bigint NOT NULL,
    id_user bigint,
    status character varying(255),
    CONSTRAINT cart_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'CHECKOUT'::character varying])::text[])))
);

-- Name: cart_id_seq; Type: SEQUENCE; Schema: public; Owner: -

ALTER TABLE public.cart ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.cart_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

