CREATE TABLE public.cart_item (
    quantity integer NOT NULL,
    cart_id bigint,
    id bigint NOT NULL,
    product_id bigint
);

-- Name: cart_item_id_seq; Type: SEQUENCE; Schema: public; Owner: -

ALTER TABLE public.cart_item ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
